function turningPointGaps(head: ListNode | null): number[] {
  const v: number[] = [];
  for (let n = head; n; n = n.next) v.push(n.val);
  const pts: number[] = [];
  for (let i = 1; i + 1 < v.length; i++) {
    if ((v[i] > v[i - 1] && v[i] > v[i + 1]) || (v[i] < v[i - 1] && v[i] < v[i + 1])) pts.push(i);
  }
  if (pts.length < 2) return [-1, -1];
  let lo = Infinity, hi = 0;
  for (let a = 0; a < pts.length; a++) {
    for (let b = a + 1; b < pts.length; b++) {
      lo = Math.min(lo, pts[b] - pts[a]);
      hi = Math.max(hi, pts[b] - pts[a]);
    }
  }
  return [lo, hi];
}

