class Solution:
    def turningPointGaps(self, head: Optional[ListNode]) -> List[int]:
        v = []
        while head:
            v.append(head.val)
            head = head.next
        pts = [i for i in range(1, len(v) - 1)
               if v[i - 1] < v[i] > v[i + 1] or v[i - 1] > v[i] < v[i + 1]]
        if len(pts) < 2:
            return [-1, -1]
        gaps = [b - a for i, a in enumerate(pts) for b in pts[i + 1:]]
        return [min(gaps), max(gaps)]

