function turningPointGaps(head: ListNode | null): number[] {
  let prevVal = head!.val, cur = head!.next, i = 1;
  let first = -1, last = -1, closest = Infinity;
  while (cur && cur.next) {
    const nextVal = cur.next.val;
    const peak = cur.val > prevVal && cur.val > nextVal;
    const dip = cur.val < prevVal && cur.val < nextVal;
    if (peak || dip) {
      if (last !== -1) closest = Math.min(closest, i - last);
      if (first === -1) first = i;
      last = i;
    }
    prevVal = cur.val;
    cur = cur.next;
    i++;
  }
  return first === last ? [-1, -1] : [closest, last - first];
}

